const NONE:usize=usize::MAX;const SEED:u64=14695981039346656037;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum BatchFailure{Envelope,Empty,Duplicate,PageMissing,NoneUnlocked,Bounds}
#[derive(Clone,Copy,Debug)]pub struct ChangedFrame{pub frame:usize,pub target:usize,pub bounds:[f64;5]}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original frame selection numeric source custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<FrameSelectionPlan>()*2+1024,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=fixed().copy_bytes;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed().copy_bytes,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=fixed().copy_bytes;p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn input(m:&impl LayoutMutationSource)->Result<(&str,&[String]),ValueError>{match m.view(){LayoutMutation::DragFrames(p)=>Ok((&p.page_id,&p.targets)),LayoutMutation::RotateFrames(p)=>Ok((&p.page_id,&p.targets)),LayoutMutation::ScaleFrames(p)=>Ok((&p.page_id,&p.targets)),_=>Err(fault())}}
fn envelope(m:&impl LayoutMutationSource)->bool{match m.view(){LayoutMutation::DragFrames(p)=>p.dx.is_finite()&&p.dy.is_finite(),LayoutMutation::RotateFrames(p)=>[p.pivot_x,p.pivot_y,p.angle].iter().all(|v|v.is_finite()),LayoutMutation::ScaleFrames(p)=>[p.pivot_x,p.pivot_y,p.sx,p.sy].iter().all(|v|v.is_finite())&&p.sx>0.0&&p.sy>0.0,_=>false}}
fn original(b:&LayoutBounds)->[f64;5]{[b.x,b.y,b.width,b.height,b.rotation]}
fn transform(m:&impl LayoutMutationSource,b:&LayoutBounds)->[f64;5]{let mut out=original(b);match m.view(){LayoutMutation::DragFrames(p)=>{out[0]+=p.dx;out[1]+=p.dy},LayoutMutation::RotateFrames(p)=>{let(sin,cos)=(p.angle.sin(),p.angle.cos());let(x,y)=(b.x+b.width*0.5-p.pivot_x,b.y+b.height*0.5-p.pivot_y);out[0]=p.pivot_x+x*cos-y*sin-b.width*0.5;out[1]=p.pivot_y+x*sin+y*cos-b.height*0.5;out[4]=b.rotation+p.angle},LayoutMutation::ScaleFrames(p)=>{let(x,y)=(b.x+b.width*0.5,b.y+b.height*0.5);out[2]=b.width*p.sx;out[3]=b.height*p.sy;out[0]=p.pivot_x+(x-p.pivot_x)*p.sx-out[2]*0.5;out[1]=p.pivot_y+(y-p.pivot_y)*p.sy-out[3]*0.5},_=>unreachable!("admitted batch transform")};out}
enum Rows<'a>{Pages(&'a[Page]),Parents(&'a[ParentPage]),Layers(&'a[Layer],usize)}
impl LayoutTargetSource for Rows<'_>{fn identity(&self)->usize{match self{Self::Pages(_)=>761,Self::Parents(_)=>762,Self::Layers(_,id)=>*id}}fn count(&self)->usize{match self{Self::Pages(r)=>r.len(),Self::Parents(r)=>r.len(),Self::Layers(r,_)=>r.len()}}fn key(&self,i:usize)->&str{match self{Self::Pages(r)=>&r[i].id,Self::Parents(r)=>&r[i].id,Self::Layers(r,_)=>&r[i].id}}}
