pub struct FrameSelectionPlan{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,positions:ManuallyDrop<Vec<usize>>,changed:ManuallyDrop<Vec<ChangedFrame>>,missing:ManuallyDrop<Vec<usize>>,locked:ManuallyDrop<Vec<usize>>,map:ManuallyDrop<ScratchHashMap<u64,usize>>,lookup:[LayoutTargetLookup;3],phase:u8,index:usize,frame:usize,other:usize,offset:usize,slot:usize,hash:u64,parent:Option<usize>,blocked:bool,closing:bool,pub page:usize,pub movable:usize,pub failure:Option<BatchFailure>,pub duplicate:Option<usize>}
